USE mccollins_shipping;SET time_zone='+00:00';START TRANSACTION;
INSERT INTO permissions(permission_code,domain_code,action_code,sensitivity,is_active)SELECT x.c,'finance',x.a,x.s,1 FROM(
SELECT 'PAYMENT_MANAGE_FINANCE' c,'manage_payment' a,'restricted' s UNION ALL SELECT 'PAYMENT_VIEW_FINANCE','view_payment','restricted'
UNION ALL SELECT 'PAYMENT_VIEW_SHIPPER','view_own_payment','normal' UNION ALL SELECT 'PAYMENT_SUBMIT_SHIPPER','submit_payment','sensitive'
UNION ALL SELECT 'SETTLEMENT_MANAGE_FINANCE','manage_settlement','restricted' UNION ALL SELECT 'SETTLEMENT_VIEW_FINANCE','view_settlement','restricted'
UNION ALL SELECT 'SETTLEMENT_VIEW_CARRIER','view_own_settlement','normal' UNION ALL SELECT 'FINANCE_VIEW_OPERATIONS','view_operations_finance','sensitive'
)x WHERE NOT EXISTS(SELECT 1 FROM permissions p WHERE p.permission_code=x.c);
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status)SELECT r.role_id,p.permission_id,'global',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON p.permission_code IN('PAYMENT_MANAGE_FINANCE','PAYMENT_VIEW_FINANCE','SETTLEMENT_MANAGE_FINANCE','SETTLEMENT_VIEW_FINANCE')WHERE r.role_code='MCCOLLIN_FINANCE' AND NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status)SELECT r.role_id,p.permission_id,'global',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON p.permission_code='FINANCE_VIEW_OPERATIONS' WHERE r.role_code='MCCOLLIN_OPERATIONS' AND NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status)SELECT r.role_id,p.permission_id,'owner',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON(r.role_code='SHIPPER' AND p.permission_code IN('PAYMENT_VIEW_SHIPPER','PAYMENT_SUBMIT_SHIPPER'))OR(r.role_code='TRUCK_OWNER' AND p.permission_code='SETTLEMENT_VIEW_CARRIER')WHERE NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');COMMIT;